package com.chatsystem.user.ui.cell;
import com.chatsystem.shared.model.ConversationMember;import com.chatsystem.shared.model.status.GroupRole;import javafx.scene.control.*;import javafx.scene.layout.*;import java.util.function.*;
public final class GroupMemberCell extends ListCell<ConversationMember>{private final BooleanSupplier canManage;private final BiConsumer<ConversationMember,GroupRole>changeRole;private final Consumer<ConversationMember>remove;private final Predicate<ConversationMember>protectedMember;public GroupMemberCell(BooleanSupplier c,BiConsumer<ConversationMember,GroupRole>r,Consumer<ConversationMember>x,Predicate<ConversationMember>p){canManage=c;changeRole=r;remove=x;protectedMember=p;}@Override protected void updateItem(ConversationMember m,boolean empty){super.updateItem(m,empty);if(empty||m==null){setText(null);setGraphic(null);return;}Label identity=new Label("Member #"+m.getUserId()+" · joined "+m.getJoinedAt());HBox.setHgrow(identity,Priority.ALWAYS);HBox row=new HBox(8,identity);if(canManage.getAsBoolean()){ChoiceBox<GroupRole>roles=new ChoiceBox<>();roles.getItems().setAll(GroupRole.values());roles.setValue(m.getRole());roles.getStyleClass().add("group-role-selector");roles.setOnAction(e->{if(roles.getValue()!=m.getRole())changeRole.accept(m,roles.getValue());});Button button=new Button("Remove");button.getStyleClass().add("group-remove-action");StackPane wrapper=new StackPane(button);if(protectedMember.test(m)){button.setDisable(true);button.setMouseTransparent(true);String reason="This protected group admin cannot be removed; the group must retain a valid admin.";wrapper.setAccessibleText(reason);Tooltip.install(wrapper,new Tooltip(reason));}else button.setOnAction(e->remove.accept(m));row.getChildren().addAll(roles,wrapper);}setText(null);setGraphic(row);}}
